import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Test {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        while (s.hasNextLine()) {
            s.nextLine();
            System.out.println(TextDocumentAnalysis.input(s.nextLine()));
        }
        s.close();
    }
}

class TextDocumentAnalysis {
    private static final Pattern WORD = Pattern.compile("[^_()]+");

    public static String input(String str) {
        int max = 0;
        int words = 0;
        Matcher m = WORD.matcher(str);
        while (m.find()) {
            int len = m.group().length();
            int end = m.end();
            if (end < str.length()) {
                char next = str.charAt(end);
                if (next == '(') {
                    if (len > max) max = len;
                } else if (next == ')') {
                    words++;
                } else {
                    int lastOpen = str.lastIndexOf('(', end - 1);
                    int lastClose = str.lastIndexOf(')', end - 1);
                    if (lastOpen > lastClose) words++;
                    else if (len > max) max = len;
                }
            } else {
                int lastOpen = str.lastIndexOf('(', end - 1);
                int lastClose = str.lastIndexOf(')', end - 1);
                if (lastOpen > lastClose) words++;
                else if (len > max) max = len;
            }
        }
        return max + " " + words;
    }
}
